import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger, revealHeadings } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { PORTFOLIO_DATA } from '@/data';

export default function About({ planetAnchor }) {
  const root = useRef(null);
  const { t, i18n } = useTranslation();
  const reducedMotion = useReducedMotion();
  const heading = t('about.heading').split(' / ');

  useGSAP((context, contextSafe) => {
    const q = gsap.utils.selector(root.current);

    if (!reducedMotion) {
      const avatar = q('.avatar-col')[0];
      const revealAvatar = avatar.getBoundingClientRect().top >= window.innerHeight * 0.85;
      const entrances = q('[data-about-reveal], .skill-pill, .tool-icon img, .tool-icon span')
        .filter((element) => element.getBoundingClientRect().top >= window.innerHeight * 0.88);

      revealHeadings(q('[data-about-heading-line], h3'), contextSafe);

      if (revealAvatar) gsap.fromTo(q('.avatar-wrap'),
        { clipPath: 'inset(12% 8% 12% 8%)', scale: 0.96, y: 40, opacity: 0 },
        {
          clipPath: 'inset(0% 0% 0% 0%)', scale: 1, y: 0, opacity: 1, duration: 1, ease: 'power3.out',
          scrollTrigger: {
            trigger: avatar, start: 'top 85%', once: true,
          },
        });

      gsap.fromTo(q('.avatar-img'), { yPercent: 3 }, {
        yPercent: -3, ease: 'none',
        scrollTrigger: {
          trigger: root.current, start: 'top bottom', end: 'bottom top', scrub: 1,
        },
      });

      if (entrances.length) {
        gsap.set(entrances, { y: 40, opacity: 0 });
        const reveal = contextSafe((elements) => gsap.to(elements, {
          y: 0, opacity: 1, duration: 1, ease: 'power3.out', stagger: 0.1, overwrite: 'auto',
        }));
        ScrollTrigger.batch(entrances, {
          start: 'top 88%', once: true, onEnter: reveal, onEnterBack: reveal,
        });
      }
    }

    // Translated paragraphs change the positions of every section below About.
    ScrollTrigger.refresh(true);
  }, { scope: root, dependencies: [reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  return (
    <section
      ref={root}
      id="about"
      data-theme="dark"
      aria-labelledby="about-heading"
      className="relative border-y border-white/[0.06] bg-transparent px-6 py-24 text-(--text-primary) sm:px-8 lg:px-12 lg:py-32"
    >
      <div className="mx-auto grid max-w-7xl grid-cols-12 items-start gap-x-0 gap-y-14 lg:gap-x-16 xl:gap-x-20">
        <figure className="avatar-col col-span-12 m-0 min-w-0 lg:col-span-5">
          <div className="relative mx-auto w-full max-w-md before:pointer-events-none before:absolute before:inset-0 before:opacity-10 before:shadow-(--glow-button)">
            <div className="avatar-wrap relative aspect-[4/5] overflow-clip border border-white/15 bg-(--bg-nebula)">
              <img
                src="/avatar.webp"
                alt={t('about.heading')}
                width="800"
                height="1000"
                loading="lazy"
                decoding="async"
                className="avatar-img absolute -top-[10%] h-[120%] w-full object-contain grayscale"
              />
            </div>
            <figcaption data-about-reveal className="mt-5 bg-(--bg-void) font-mono text-xs leading-relaxed tracking-[0.1em] text-(--text-muted)">
              {t('about.photoCaption')}
            </figcaption>
            <div
              ref={planetAnchor}
              data-planet-window
              aria-hidden="true"
              className="mt-8 h-56 border-y border-white/10 sm:h-64 lg:h-72"
            />
          </div>
        </figure>

        <div className="col-span-12 min-w-0 bg-(--bg-void) lg:col-span-7">
          <p data-about-reveal className="mb-6 font-mono text-xs uppercase tracking-[0.2em] text-(--text-secondary)">
            {t('about.sectionLabel')}
          </p>
          {/* Replace the whole heading on language changes: SplitText owns its inner DOM. */}
          <h2
            key={i18n.resolvedLanguage}
            id="about-heading"
            aria-label={t('about.heading')}
            className="about-title font-display text-[clamp(1.75rem,5vw,4rem)] font-bold leading-[1.18] tracking-[-0.035em] uppercase"
          >
            <span data-about-heading-line className="split-heading block">{heading[0]}</span>
            <span data-about-heading-line className="split-heading stroke-text-white block">{heading[1]}</span>
          </h2>
          <p data-about-reveal className="mt-5 font-mono text-xs leading-relaxed tracking-[0.02em] text-(--text-secondary) sm:text-sm">
            {t('about.subLabel')}
          </p>

          <div className="mt-10 max-w-[62ch] space-y-5 font-body text-base leading-[1.75] text-(--text-secondary) lg:text-lg">
            <p data-about-reveal className="text-base leading-[1.75] lg:text-lg">{t('about.bioFirst')}</p>
            <p data-about-reveal className="text-base leading-[1.75] lg:text-lg">{t('about.bioSecond')}</p>
          </div>

          <blockquote data-about-reveal className="my-10 border-l border-white/20 pl-6 font-body text-xl font-light italic leading-relaxed tracking-[-0.01em] sm:text-2xl">
            {t('about.quote')}
          </blockquote>

          <div className="border-t border-white/[0.06] pt-8">
            <h3 key={i18n.resolvedLanguage} aria-label={t('about.toolsLabel')} id="about-tools" className="split-heading font-mono text-xs font-normal leading-relaxed tracking-[0.15em]">
              {t('about.toolsLabel')}
            </h3>
            <ul aria-labelledby="about-tools" className="tools-row mt-5 flex list-none flex-wrap items-center gap-3 p-0">
              {PORTFOLIO_DATA.tools.map((tool) => (
                <li
                  key={tool.id}
                  data-magnetic
                  title={t(`about.tools.${tool.id}`)}
                  className="tool-icon flex h-12 items-center justify-center border border-white/10 bg-white/[0.03] px-3 hover:border-white/30 sm:h-14"
                >
                  {tool.icon ? (
                    <img
                      src={tool.icon}
                      alt={t(`about.tools.${tool.id}`)}
                      width="32"
                      height="32"
                      loading="lazy"
                      className="size-7 object-contain grayscale opacity-80 transition-opacity duration-200 hover:opacity-100 sm:size-8"
                    />
                  ) : (
                    <span className="font-mono text-xs text-(--text-secondary)">{t(`about.tools.${tool.id}`)}</span>
                  )}
                </li>
              ))}
            </ul>
          </div>

          <div className="mt-8">
            <h3 key={i18n.resolvedLanguage} aria-label={t('about.skillsLabel')} id="about-skills" className="split-heading font-mono text-xs font-normal leading-relaxed tracking-[0.15em]">
              {t('about.skillsLabel')}
            </h3>
            <ul aria-labelledby="about-skills" className="mt-5 flex list-none flex-wrap gap-2 p-0">
              {PORTFOLIO_DATA.skills.map((skill, index) => (
                <li key={skill} className="skill-pill max-w-full rounded-full border border-white/10 bg-white/[0.03] px-4 py-2 font-body text-xs leading-relaxed text-(--text-secondary) hover:border-white/35 hover:text-(--text-primary)">
                  {t(`about.coreSkills.${index}`)}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

